schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/agency-risk-register-template.json",
  "title": "Agency risk register (Monday refresh)",
  "type": "object",
  "required": ["agency", "refresh", "concentration", "rows", "closed"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "score": {"type": "integer", "minimum": 1, "maximum": 5},
    "share": {"type": "number", "minimum": 0, "maximum": 1},
    "person": {"type": "string", "minLength": 3, "not": {"enum": ["team", "ops", "everyone", "tbd", "the team", "management"]}},
    "risk_class": {"type": "string", "enum": ["revenue_concentration", "key_person", "fx_currency", "contractor_classification", "pipeline_thinness", "regulatory"]},
    "currency_shares": {"type": "object", "minProperties": 1, "propertyNames": {"pattern": "^[A-Z]{3}$"}, "additionalProperties": {"$ref": "#/definitions/share"}}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "agency": {
      "type": "object",
      "required": ["name", "headcount"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 2},
        "headcount": {"type": "integer", "minimum": 3, "maximum": 25}
      }
    },
    "refresh": {
      "type": "object",
      "required": ["date", "minutes", "consecutive_overruns", "split_or_prune_required", "action_note"],
      "additionalProperties": false,
      "properties": {
        "date": {"$ref": "#/definitions/date"},
        "minutes": {
          "type": "object",
          "required": ["scores_update", "top5_walk", "action_note", "total"],
          "additionalProperties": false,
          "properties": {
            "scores_update": {"type": "integer", "minimum": 0},
            "top5_walk": {"type": "integer", "minimum": 0},
            "action_note": {"type": "integer", "minimum": 0},
            "total": {"type": "integer", "minimum": 1}
          }
        },
        "consecutive_overruns": {"type": "integer", "minimum": 0},
        "split_or_prune_required": {"type": "boolean"},
        "action_note": {"type": "string", "minLength": 20}
      },
      "if": {"properties": {"consecutive_overruns": {"minimum": 2}}},
      "then": {"properties": {"split_or_prune_required": {"const": true}}}
    },
    "concentration": {
      "type": "object",
      "required": ["source", "trailing_days", "recomputed_on", "clients"],
      "additionalProperties": false,
      "properties": {
        "source": {"const": "billing_export"},
        "trailing_days": {"const": 90},
        "recomputed_on": {"$ref": "#/definitions/date"},
        "clients": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["name", "share"],
            "additionalProperties": false,
            "properties": {"name": {"type": "string", "minLength": 2}, "share": {"$ref": "#/definitions/share"}}
          }
        }
      }
    },
    "rows": {
      "type": "array",
      "minItems": 6,
      "allOf": [
        {"contains": {"properties": {"class": {"const": "revenue_concentration"}}}},
        {"contains": {"properties": {"class": {"const": "key_person"}}}},
        {"contains": {"properties": {"class": {"const": "fx_currency"}}}},
        {"contains": {"properties": {"class": {"const": "contractor_classification"}}}},
        {"contains": {"properties": {"class": {"const": "pipeline_thinness"}}}},
        {"contains": {"properties": {"class": {"const": "regulatory"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["id", "class", "description", "likelihood", "impact", "score", "owner", "trigger", "details", "response"],
        "additionalProperties": false,
        "properties": {
          "id": {"type": "string", "pattern": "^R-[0-9]{2,}$"},
          "class": {"$ref": "#/definitions/risk_class"},
          "description": {"type": "string", "minLength": 15},
          "likelihood": {"$ref": "#/definitions/score"},
          "impact": {"$ref": "#/definitions/score"},
          "score": {"type": "integer", "minimum": 1, "maximum": 25},
          "owner": {"$ref": "#/definitions/person"},
          "trigger": {"type": "string", "minLength": 25},
          "details": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "client": {"type": "string", "minLength": 2},
              "share": {"$ref": "#/definitions/share"},
              "item": {"type": "string", "minLength": 5},
              "holder": {"$ref": "#/definitions/person"},
              "remediation_owner": {"$ref": "#/definitions/person"},
              "deadline": {"$ref": "#/definitions/date"},
              "revenue_share_by_currency": {"$ref": "#/definitions/currency_shares"},
              "cost_share_by_currency": {"$ref": "#/definitions/currency_shares"},
              "contractors": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "object",
                  "required": ["name", "jurisdiction", "test", "outcome"],
                  "additionalProperties": false,
                  "properties": {
                    "name": {"type": "string", "minLength": 2},
                    "jurisdiction": {"type": "string", "minLength": 2},
                    "test": {"type": "string", "minLength": 5},
                    "outcome": {"type": "string", "enum": ["contractor", "employee_risk", "unresolved"]},
                    "fix_due": {"$ref": "#/definitions/date"}
                  },
                  "if": {"properties": {"outcome": {"enum": ["employee_risk", "unresolved"]}}},
                  "then": {"required": ["fix_due"]}
                }
              },
              "weighted_pipeline": {"type": "number", "minimum": 0},
              "monthly_cost_base": {"type": "number", "exclusiveMinimum": 0},
              "months_of_coverage": {"type": "number", "minimum": 0},
              "trigger_below_months": {"type": "number", "exclusiveMinimum": 0},
              "regulation": {"type": "string", "minLength": 3}
            }
          },
          "response": {
            "anyOf": [
              {"type": "null"},
              {
                "type": "object",
                "required": ["kind"],
                "additionalProperties": false,
                "properties": {
                  "kind": {"type": "string", "enum": ["mitigation", "acceptance"]},
                  "action": {"type": "string", "minLength": 10},
                  "owner": {"$ref": "#/definitions/person"},
                  "due_date": {"$ref": "#/definitions/date"},
                  "signed_by": {"$ref": "#/definitions/person"},
                  "signed_on": {"$ref": "#/definitions/date"}
                },
                "allOf": [
                  {"if": {"properties": {"kind": {"const": "mitigation"}}}, "then": {"required": ["action", "owner", "due_date"]}},
                  {"if": {"properties": {"kind": {"const": "acceptance"}}}, "then": {"required": ["signed_by", "signed_on"]}}
                ]
              }
            ]
          }
        },
        "allOf": [
          {"if": {"properties": {"class": {"const": "revenue_concentration"}}}, "then": {"properties": {"details": {"required": ["client", "share"]}}}},
          {"if": {"properties": {"class": {"const": "key_person"}}}, "then": {"properties": {"details": {"required": ["item", "holder", "remediation_owner", "deadline"]}}}},
          {"if": {"properties": {"class": {"const": "fx_currency"}}}, "then": {"properties": {"details": {"required": ["revenue_share_by_currency", "cost_share_by_currency"]}}}},
          {"if": {"properties": {"class": {"const": "contractor_classification"}}}, "then": {"properties": {"details": {"required": ["contractors"]}}}},
          {"if": {"properties": {"class": {"const": "pipeline_thinness"}}}, "then": {"properties": {"details": {"required": ["weighted_pipeline", "monthly_cost_base", "months_of_coverage", "trigger_below_months"]}}}},
          {"if": {"properties": {"class": {"const": "regulatory"}}}, "then": {"properties": {"details": {"required": ["regulation"]}}}},
          {"if": {"properties": {"score": {"minimum": 15}}}, "then": {"properties": {"response": {"type": "object"}}}}
        ]
      }
    },
    "closed": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "class", "description", "closed_on", "lesson"],
        "additionalProperties": false,
        "properties": {
          "id": {"type": "string", "pattern": "^R-[0-9]{2,}$"},
          "class": {"$ref": "#/definitions/risk_class"},
          "description": {"type": "string", "minLength": 15},
          "closed_on": {"$ref": "#/definitions/date"},
          "lesson": {"type": "string", "minLength": 15}
        }
      }
    }
  }
}

example.code:
{
  "agency": {"name": "Brightline Studio", "headcount": 6},
  "refresh": {
    "date": "2026-09-14",
    "minutes": {"scores_update": 5, "top5_walk": 15, "action_note": 8, "total": 28},
    "consecutive_overruns": 0,
    "split_or_prune_required": false,
    "action_note": "Client A at 47 percent: Dana sends proposals to Harbor Logistics and Vireo by Friday; AWS root hand-over to Priya scheduled for 2026-09-30; USD/EUR mismatch accepted for this quarter pending the hedging quote."
  },
  "concentration": {
    "source": "billing_export",
    "trailing_days": 90,
    "recomputed_on": "2026-09-14",
    "clients": [
      {"name": "Client A", "share": 0.47},
      {"name": "Client B", "share": 0.22},
      {"name": "Client C", "share": 0.12},
      {"name": "others", "share": 0.19}
    ]
  },
  "rows": [
    {"id": "R-01", "class": "revenue_concentration", "description": "Client A is 47 percent of trailing-90-day revenue", "likelihood": 4, "impact": 5, "score": 20, "owner": "Dana Kovac", "trigger": "Client A misses two invoices in a row or cancels the weekly sync", "details": {"client": "Client A", "share": 0.47}, "response": {"kind": "mitigation", "action": "send proposals to Harbor Logistics and Vireo", "owner": "Dana Kovac", "due_date": "2026-09-18"}},
    {"id": "R-02", "class": "revenue_concentration", "description": "Client B is 22 percent of trailing-90-day revenue", "likelihood": 3, "impact": 3, "score": 9, "owner": "Dana Kovac", "trigger": "Client B retainer not renewed 30 days before its 2026-12-31 end date", "details": {"client": "Client B", "share": 0.22}, "response": null},
    {"id": "R-03", "class": "key_person", "description": "AWS root credentials and the deploy pipeline are known only to Marko", "likelihood": 3, "impact": 4, "score": 12, "owner": "Dana Kovac", "trigger": "Marko unavailable for more than 5 working days with no backup holder", "details": {"item": "AWS root credentials and deploy pipeline", "holder": "Marko Ilic", "remediation_owner": "Priya Nair", "deadline": "2026-09-30"}, "response": null},
    {"id": "R-04", "class": "fx_currency", "description": "60 percent of revenue billed in USD against 90 percent of costs in EUR", "likelihood": 4, "impact": 3, "score": 12, "owner": "Dana Kovac", "trigger": "EUR/USD moves more than 5 percent against the quarter's opening rate", "details": {"revenue_share_by_currency": {"USD": 0.6, "EUR": 0.4}, "cost_share_by_currency": {"EUR": 0.9, "USD": 0.1}}, "response": null},
    {"id": "R-05", "class": "contractor_classification", "description": "One cross-border contractor on a 30-hour week for a single client", "likelihood": 2, "impact": 4, "score": 8, "owner": "Dana Kovac", "trigger": "Contractor exceeds 35 hours a week for 8 weeks or loses the right to substitute", "details": {"contractors": [{"name": "Ana Ferreira", "jurisdiction": "Portugal", "test": "control, substitution and financial risk (recibos verdes regime)", "outcome": "contractor"}]}, "response": null},
    {"id": "R-06", "class": "pipeline_thinness", "description": "Stage-weighted pipeline covers 3.5 months of the cost base", "likelihood": 3, "impact": 4, "score": 12, "owner": "Dana Kovac", "trigger": "Weighted coverage below 3 months at any Monday refresh", "details": {"weighted_pipeline": 210000, "monthly_cost_base": 60000, "months_of_coverage": 3.5, "trigger_below_months": 3}, "response": null},
    {"id": "R-07", "class": "regulatory", "description": "GDPR processor agreements not yet signed with two clients", "likelihood": 2, "impact": 3, "score": 6, "owner": "Priya Nair", "trigger": "A client audit request or a data incident arrives before both agreements are signed", "details": {"regulation": "GDPR Article 28 processor agreements"}, "response": null}
  ],
  "closed": [
    {"id": "R-00", "class": "key_person", "description": "Domain registrar account held only by the founder", "closed_on": "2026-08-31", "lesson": "Shared credentials go into the password manager on day one, not after the first scare"}
  ]
}

{
  "agency": {"name": "Brightline Studio", "headcount": 6},
  "refresh": {
    "date": "2026-09-16",
    "minutes": {"scores_update": 10, "top5_walk": 45, "action_note": 20, "total": 60},
    "consecutive_overruns": 2,
    "split_or_prune_required": false,
    "action_note": "Reviewed everything, nothing new."
  },
  "concentration": {
    "source": "founder_estimate",
    "trailing_days": 365,
    "recomputed_on": "2026-06-01",
    "clients": [{"name": "Client A", "share": 0.47}]
  },
  "rows": [
    {"id": "R-01", "class": "revenue_concentration", "description": "Client A might churn at some point", "likelihood": 4, "impact": 5, "score": 18, "owner": "team", "trigger": "if things get worse", "details": {"client": "Client A", "share": 0.3}, "response": null},
    {"id": "R-02", "class": "key_person", "description": "We should cross-train on the deploy pipeline", "likelihood": 3, "impact": 4, "score": 12, "owner": "ops", "trigger": "someone leaves", "details": {"item": "deploy pipeline", "holder": "Marko Ilic"}, "response": null},
    {"id": "R-03", "class": "fx_currency", "description": "Some USD exposure on a couple of clients", "likelihood": 3, "impact": 3, "score": 9, "owner": "Dana Kovac", "trigger": "the dollar moves a lot against the euro", "details": {}, "response": null},
    {"id": "R-04", "class": "pipeline_thinness", "description": "Pipeline feels thin for the autumn", "likelihood": 3, "impact": 4, "score": 12, "owner": "Dana Kovac", "trigger": "we notice there is not enough work", "details": {"weighted_pipeline": 120000, "monthly_cost_base": 60000, "months_of_coverage": 4, "trigger_below_months": 3}, "response": null},
    {"id": "P-17", "class": "project_scope_slip", "description": "Sprint 4 of the Client C build is two weeks late", "likelihood": 4, "impact": 2, "score": 8, "owner": "Marko Ilic", "trigger": "Sprint 5 also slips by more than a week", "details": {}, "response": null},
    {"id": "P-18", "class": "project_vendor", "description": "Payment gateway vendor slow on the Client B integration", "likelihood": 3, "impact": 2, "score": 6, "owner": "Marko Ilic", "trigger": "Vendor misses the next scheduled delivery date too", "details": {}, "response": null}
  ],
  "closed": []
}
